-- Deploy targets (docs/ARCHITECTURE.md §5 "Deploy targets", docs/DEPLOY.md).
--
-- One SSH key pair per project, generated by the server. The private key is stored only encrypted with the master key
-- (SecretBox, associated data `deploy-key:<repo>`) and decrypted in memory for one connection at a time.
CREATE TABLE deploy_keys (
    repo            TEXT PRIMARY KEY,
    public_key      TEXT NOT NULL,              -- the authorized_keys line: ssh-ed25519 <base64> agern-deploy:<org>/<repo>
    fingerprint     TEXT NOT NULL,              -- SHA256:<base64 without padding>
    private_key_enc BYTEA NOT NULL,
    created_by      UUID NOT NULL REFERENCES users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- An admin approves a project's `.agern/deploy.yml` by the SHA-256 of its exact content, like sandbox_approvals.
CREATE TABLE deploy_approvals (
    repo        TEXT PRIMARY KEY,
    sha256      TEXT NOT NULL,
    content     TEXT NOT NULL,              -- the approved file, for display and diffs
    approved_by UUID NOT NULL REFERENCES users(id),
    approved_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
